{
  "name": "光束剖面强度监视器",
  "name_en": "Profile Intensity Monitor",
  "manufacturer": "",
  "description": "用于束线诊断的光束剖面强度监视器。该设备通过Y向插入/移出机构将YAG靶或二极管送入光路，并结合变焦机构和面阵探测器来观察光束形貌与强度分布；部分变体还带有调焦或LED照明功能。",
  "description_en": "A beam diagnostics profile intensity monitor. It inserts or retracts a YAG target or diode into the beam path via a Y-axis mechanism, and uses zoom optics with an area detector to observe beam profile and intensity distribution; some variants also include focus control or LED illumination.",
  "actions": [
    {
      "action_name": "auto-format_status_info",
      "description": "格式化并显示该监视器的状态信息。",
      "description_en": "Format and display the monitor status information."
    },
    {
      "action_name": "auto-infer_prefix",
      "description": "根据给定前缀推断PV前缀的起始部分。",
      "description_en": "Infer the starting portion of the PV prefix from the given prefix."
    },
    {
      "action_name": "auto-insert",
      "description": "将YAG插入光束路径。",
      "description_en": "Insert the YAG into the beam path."
    },
    {
      "action_name": "auto-remove",
      "description": "将YAG和二极管移出光束路径。",
      "description_en": "Remove the YAG and diode from the beam path."
    },
    {
      "action_name": "auto-stage",
      "description": "使设备进入实验准备状态。",
      "description_en": "Stage the device for experimental use."
    },
    {
      "action_name": "auto-unstage",
      "description": "将设备退出实验准备状态。",
      "description_en": "Unstage the device after use."
    },
    {
      "action_name": "auto-prefix_start",
      "description": "获取PV前缀的前两段。",
      "description_en": "Get the first two segments of the PV prefix."
    },
    {
      "action_name": "auto-removed",
      "description": "获取YAG和二极管是否已移出光束路径。",
      "description_en": "Get whether the YAG and diode are removed from the beam path."
    },
    {
      "action_name": "auto-inserted",
      "description": "获取YAG或二极管是否已插入光束路径。",
      "description_en": "Get whether the YAG or diode is inserted into the beam path."
    },
    {
      "action_name": "auto-y_states",
      "description": "获取Y轴位置状态选项。",
      "description_en": "Get the Y-axis position state options."
    }
  ],
  "tag_hints": [
    "beam diagnostics",
    "profile intensity monitor",
    "YAG screen insertion",
    "beam imaging",
    "area detector",
    "zoom optics",
    "lightpath control"
  ]
}

